  "group": "antipattern",
  "description": "Warns when catch callbacks return unknown instead of typed errors",
  "defaultSeverity": "warning",
  "fixable": false,
  "supportedEffect": [
    "v3",
    "v4"
  ],
  "codes": [
    377021
  ],
